fn date_at_utc(value: &str) -> Result<chrono::DateTime<Utc>, EventServiceError> {
    let date = NaiveDate::parse_from_str(value, "%Y-%m-%d")
        .map_err(|_| EventServiceError::InvalidInput)?;
    Ok(date
        .and_hms_opt(0, 0, 0)
        .ok_or(EventServiceError::InvalidInput)?
        .and_utc())
}

#[derive(Debug)]
